// ─── HELPER FUNCTIONS ───
function getStudentsByDept(dept, level) {
  return ICEP_STUDENTS.filter(s => s.department === dept && (level ? s.level === level : true));
}
function getRepByDeptLevel(dept, level) {
  return ICEP_COURSE_REPS.find(r => r.department === dept && r.level === level) || null;
}
function getCoordinatorByFaculty(faculty) {
  return ICEP_COORDINATORS.find(c => c.faculty === faculty) || null;
}
function filterStudents({ faculty, department, level, role, text } = {}) {
  let pool = [...ICEP_STUDENTS, ...ICEP_COURSE_REPS.map(r => ({...r, role:'Course Rep'}))];
  if (faculty) pool = pool.filter(p => p.faculty === faculty);
  if (department) pool = pool.filter(p => p.department === department);
  if (level) pool = pool.filter(p => p.level === Number(level));
  if (role === 'Course Rep') pool = ICEP_COURSE_REPS.filter(r => {
    if (faculty && r.faculty !== faculty) return false;
    if (department && r.department !== department) return false;
    if (level && r.level !== Number(level)) return false;
    if (text && !r.name.toLowerCase().includes(text) && !r.matric.toLowerCase().includes(text)) return false;
    return true;
  });
  else if (role === 'Student') pool = ICEP_STUDENTS.filter(s => {
    if (faculty && s.faculty !== faculty) return false;
    if (department && s.department !== department) return false;
    if (level && s.level !== Number(level)) return false;
    if (text && !s.name.toLowerCase().includes(text) && !s.matric.toLowerCase().includes(text)) return false;
    return true;
  });
  else if (text) pool = pool.filter(p => p.name.toLowerCase().includes(text) || p.matric.toLowerCase().includes(text));
  return pool;
}
